545	const N=7;const dots=document.querySelectorAll('.dot');
546	function tick(i,btn){btn.classList.toggle('ticked');dots[i].classList.toggle('done');}
547	let answered=0;const total=5;
548	function upScore(){document.getElementById('score').textContent=`${answered} / ${total} answered`;}
549	function shuf(a){for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
550	document.querySelectorAll('.qblock').forEach(qb=>{
551	  const list=qb.querySelector('.opts');
552	  shuf([...list.children]).forEach(li=>list.appendChild(li));
553	  const qn=qb.dataset.q;const fb=document.getElementById('fb'+qn);
554	  list.querySelectorAll('li').forEach(li=>{
555	    li.addEventListener('click',()=>{
556	      if(li.classList.contains('lk'))return;
557	      list.querySelectorAll('li').forEach(x=>x.classList.add('lk'));
558	      const ok=li.dataset.correct==='true';
559	      li.classList.add(ok?'ok':'no');
560	      if(!ok)list.querySelector('[data-correct="true"]')?.classList.add('ok');
561	      fb.style.display='block';fb.className='fb '+(ok?'ok':'no');
562	      fb.textContent=(ok?'✓ Correct. ':'✗ Not quite. ')+li.dataset.why;
563	      answered++;upScore();
564	    });
565	  });
566	});
567	function rev(btn){
568	  const ans=btn.nextElementSibling;
569	  ans.style.display=ans.style.display==='block'?'none':'block';
570	  btn.textContent=ans.style.display==='block'?'Hide':'Show answer';
571	}
572	</script>
